\begin{equation}\label{eq:P}
	\minimize_{s\in\R^p} \varphi(s)\equiv\sDRS(s)+\nsDRS(s).
\end{equation}

Here, \(\func{\sDRS,\nsDRS}{\R^p}{\Rinf}\) are proper, lower semicontinuous (lsc), extended-real-valued functions (\(\Rinf\coloneqq\R\cup\set\infty\) denotes the extended-real line).
Starting from some \(s\in\R^p\), one DR-iteration applied to \eqref{eq:P} with \emph{stepsize} \(\gamma>0\) and \emph{relaxation} parameter \(\lambda>0\) amounts to
\[
	\tag{DRS}\label{DRS}
% 	\renewcommand\arraystretch{1.5}
	\begin{cases}[rl]
		u\phantom{^+}
	{}\in{} &
		\prox_{\gamma\sDRS}(s)
	\\
		v\phantom{^+}
	{}\in{} &
		\prox_{\gamma\nsDRS}(2u-s)
	\\
		s^+
	{}={} &
		s+\lambda(v-u).
	\end{cases}
\]

			The extended-real line is \(\Rinf=\R\cup\set{\infty}\).
The positive and negative parts of \(r\in\R\) are defined respectively as
\(
	[r]_+
{}\coloneqq{}
	\max\set{0,r}
\)
and
\(
	[r]_-
{}\coloneqq{}
	\max\set{0,-r}
\),
so that \(r=[r]_+-[r]_-\).
We adopt the convention that \(\nicefrac10=\infty\).


For a set \(E\) and a sequence \(\seq{x^k}\) we write \(\seq{x^k}\subset E\) to indicate that \(x^k\in E\) for all \(k\in\N\).
We say that \(\seq{x^k}\subset\R^n\) is \DEF{summable} if \(\sum_{k\in\N}\|x^k\|\) is finite, and \DEF{square-summable} if \(\seq{\|x^k\|^2}\) is summable.


The \DEF{domain} of an extended-real-valued function \(\func{h}{\R^n}{\Rinf}\) is the set
\(
	\dom h
{}\coloneqq{}
	\set{x\in\R^n}[
		h(x)<\infty
	]
\),
while its \DEF{epigraph} is the set
\(
	\epi h
{}\coloneqq{}
	\set{(x,\alpha)\in\R^n\times\R}[
		h(x)\leq\alpha
	]
\).
\(h\) is said to be \DEF{proper} if \(\dom h\neq\emptyset\), and \DEF{lower semicontinuous (lsc)} if \(\epi h\) is a closed subset of \(\R^{n+1}\).
For \(\alpha\in\R\), \(\lev_{\leq\alpha}h\) is the \DEF{\(\alpha\)-level set} of \(h\), \ie
\(
	\lev_{\leq\alpha}h
{}\coloneqq{}
	\set{x\in\R^n}[
		h(x)\leq\alpha
	]
\).
We say that \(h\) is \emph{level bounded} if \(\lev_{\leq\alpha}h\) is bounded for all \(\alpha\in\R\).


We use the notation \(\ffunc H{\R^n}{\R^m}\) to indicate a point-to-set mapping \(\func H{\R^n}{\mathcal P(\R^m)}\), where \(\mathcal P(\R^m)\) is the power set of \(\R^m\) (the set of all subsets of \(\R^m\)).
The \DEF{graph} of \(H\) is the set
\(
	\graph H
{}\coloneqq{}
	\set{(x,y)\in\R^n\times\R^m}[
		y\in H(x)
	]
\).

% =============================================================================================== %

We denote by \(\ffunc{\hat\partial h}{\R^n}{\R^n}\) the \DEF{regular subdifferential} of \(h\), where
\begin{equation}\label{eq:hatpartial}
	v\in\hat\partial h(\bar x)
\quad\Leftrightarrow\quad
	\liminf_{\limsubstack{x&\to&\bar x\\x&\neq&\bar x}}{
		\frac{h(x)-h(\bar x)-\innprod{v}{x-\bar x}}{\|x-\bar x\|}
	}
{}\geq{}
	0.
\end{equation}
A necessary condition for local minimality of \(x\) for \(h\) is \(0\in\hat\partial h(x)\), see \cite[Thm. 10.1]{rockafellar2011variational}.
The (limiting) \DEF{subdifferential} of \(h\) is \(\ffunc{\partial h}{\R^n}{\R^n}\), where
\(
	v\in\partial h(\bar x)
\)
iff there exists a sequence \(\seq{x^k,v^k}\subseteq\graph\hat\partial h\) such that
\[
	\lim_{k\to\infty}(x^k,h(x^k),v^k)
{}={}
	(x,h(x),v).
\]


			The class of functions \(\func{h}{\R^n}{\R}\) that are \(k\) times continuously differentiable is denoted as \(\cont^k(\R^n)\).
We write \(h\in\cont^{1,1}(\R^n)\) to indicate that \(h\in\cont^1(\R^n)\) and that \(\nabla h\) is Lipschitz continuous with modulus \(L_h\).
To simplify the terminology, we will say that such an \(h\) is \DEF{\(L_h\)-smooth}.
It follows from \cite[Prop. A.24]{bertsekas2016nonlinear} that if \(h\) is \(L_h\)-smooth, then
\(
	|h(y)-h(x)-\innprod{\nabla h(x)}{y-x}|
{}\leq{}
	\tfrac{L_h}{2}\|y-x\|^2
\)
for all \(x,y\in\R^n\).
In particular, there exists \(\sigma_h\in[-L_h,L_h]\) such that \(h\) is \DEF{\(\sigma_h\)-hypoconvex}, in the sense that \(h-\tfrac{\sigma_h}{2}\|{}\cdot{}\|^2\) is a convex function.
Thus, every \(L_h\)-smooth and \(\sigma_h\)-hypoconvex function \(h\) satisfies
\begin{equation}\label{eq:LipBound}
	\tfrac{\sigma_h}{2}
	\|y-x\|^2
{}\leq{}
	h(y)-h(x)-\innprod{\nabla h(x)}{y-x}
{}\leq{}
	\tfrac{L_h}{2}
	\|y-x\|^2
\quad
	\forall x,y\in\R^n.
\end{equation}
By applying \cite[Thm. 2.1.5]{nesterov2003introductory} to the (convex) function \(\psi=h-\tfrac\sigma2\|{}\cdot{}\|^2\) we obtain that this is equivalent to having
\begin{equation}\label{eq:innprod}
	\sigma_h
	\|y-x\|^2
{}\leq{}
	\innprod{\nabla h(y)-\nabla h(x)}{y-x}
{}\leq{}
	L_h
	\|y-x\|^2
\quad
	\forall x,y\in\R^n.
\end{equation}
Note that \(\sigma\)-hypoconvexity generalizes the notion of (strong) convexity by allowing negative strong convexity moduli.
In fact, if \(\sigma=0\) then \(\sigma\)-hypoconvexity reduces to convexity, while for \(\sigma>0\) it denotes \(\sigma\)-strong convexity.


			The \DEF{proximal mapping} of \(\func{h}{\R^n}{\Rinf}\) with parameter \(\gamma>0\) is \(\ffunc{\prox_{\gamma h}}{\R^n}{\dom h}\) defined as
\begin{equation}
	\prox_{\gamma h}(x)
{}\coloneqq{}
	\argmin_{w\in\R^n}\set{
		h(w) + \tfrac{1}{2\gamma}\|w-x\|^2
	}.
\end{equation}
We say that a function \(h\) is \DEF{prox-bounded} if \(h+\tfrac{1}{2\gamma}\|{}\cdot{}\|^2\) is lower bounded for some \(\gamma>0\).
The supremum of all such \(\gamma\)
% --- which is possibly infinite, as it is the case when \(h\) is lower bounded or convex ---
is the \emph{threshold of prox-boundedness of \(h\)}, denoted as \(\gamma_h\).
If \(h\) is lsc, then \(\prox_{\gamma h}\) is nonempty- and compact-valued over \(\R^n\) for all \(\gamma\in(0,\gamma_h)\) \cite[Thm. 1.25]{rockafellar2011variational}.
Consequently, the value function of the minimization problem defining the proximal mapping, namely the \DEF{Moreau envelope} with stepsize \(\gamma\in(0,\gamma_h)\), denoted by \(\func{h^\gamma}{\R^n}{\R}\) and defined as
\begin{equation}
	\fillwidthof[r]{
		\prox_{\gamma h}(x)
	}{
		h^\gamma(x)
	}
{}\coloneqq{}
	\fillwidthof[l]{
		\argmin_{w\in\R^n}\set{
			h(w) + \tfrac{1}{2\gamma}\|w-x\|^2
		}.
	}{
		\inf_{w\in\R^n}\set{
			h(w) + \tfrac{1}{2\gamma}\|w-x\|^2
		},
	}
\end{equation}
is everywhere finite and, in fact, strictly continuous \cite[Ex. 10.32]{rockafellar2011variational}.
Moreover, the necessary optimality conditions of the problem defining \(\prox_{\gamma g}\) together with \cite[Thm. 10.1 and Ex. 8.8]{rockafellar2011variational} imply that
\begin{equation}\label{eq:prox:subdiff}
	\tfrac1\gamma(x-\bar x)
{}\in{}
	\hat\partial h(\bar x)
\quad
	\forall\bar x\in\prox_{\gamma h}(x).
\end{equation}


\begin{ass}[Requirements for the DRS formulation \eqref{eq:P}]\label{ass:DRS}%
	The following hold
	\begin{enumerate}
	\item\label{ass:DRS:f}%
		\(\sDRS\in\cont^{1,1}(\R^n)\) is \(L_{\sDRS}\)-smooth, hence \(\sigma_{\sDRS}\)-hypoconvex for some \(\sigma_{\sDRS}\in[-L_{\sDRS},L_{\sDRS}]\).
	\item\label{ass:DRS:g}%
		\(\nsDRS\) is proper and lsc.
	\item\label{ass:DRS:LB}%
		Problem \eqref{eq:P} has a solution, that is, \(\argmin\varphi\neq\emptyset\).
	\end{enumerate}
\end{ass}

\begin{rem}[Feasible stepsizes for \ref{DRS}]\label{thm:proxbounded}%
	Under \Cref{ass:DRS}, both \(\sDRS\) and \(\nsDRS\) are prox-bounded with threshold at least \(\nicefrac{1}{L_{\sDRS}}\), and in particular \ref{DRS} iterations are well defined for all \(\gamma\in(0,\nicefrac{1}{L_{\sDRS}})\).


Starting from \(s\in\R^p\), let us consider variables \((u,v)\) generated by a \ref{DRS} step under \Cref{ass:DRS}.
As first noted in \cite{patrinos2014douglas}, from the relation \(s=u+\gamma\nabla\sDRS(u)\) (see \cref{thm:proxfEquiv}) it follows that
\begin{equation}\label{eq:vFBS}
	v\in\FB u
\end{equation}
is the result of a \DEF{forward-backward step} at \(u\), amounting to
\begin{align}\label{eq:DRSv}
	v
{}\in{}
	\argmin_{w\in\R^p}{} &
	\set{
		\nsDRS(w)
		{}+{}
		\smashunderbracket{
			\sDRS(u)
			{}+{}
			\innprod{\nabla\sDRS(u)}{w-u}
			{}+{}
			\tfrac{1}{2\gamma}\|w-u\|^2
		}{}
	},
\shortintertext{%
	see \eg \cite{bolte2014proximal,themelis2018forward} for an extensive discussion on nonconvex forward-backward splitting (FBS).
	This shows that \(v\) is the result of the minimization of a \emph{majorization model} for the original function \(\varphi=\sDRS+\nsDRS\), where the smooth function \(\sDRS\) is replaced by the quadratic upper bound emphasized by the under-bracket in \eqref{eq:DRSv}.
	First introduced in \cite{patrinos2014douglas} for convex problems, the \DEF{Douglas-Rachford envelope} (DRE) is the function \(\func{\DRE}{\R^n}{\R}\) defined as%
}
\label{eq:DRE}
	\DRE(s)
{}\coloneqq{}
	\min_{w\in\R^p}{} &
	\set{
		\nsDRS(w)
		{}+{}
		\sDRS(u)
		{}+{}
		\innprod{\nabla\sDRS(u)}{w-u}
		{}+{}
		\tfrac{1}{2\gamma}\|w-u\|^2
	}.
\end{align}

Namely, rather than the \emph{minimizer} \(v\), \(\DRE(s)\) is the \emph{value} of the minimization problem \eqref{eq:DRSv} defining the \(v\)-update in \eqref{DRS}.
The expression \eqref{eq:DRE} emphasizes the close connection that the DRE has with the \DEF{forward-backward envelope} (FBE) as in \cite{themelis2018forward}, here denoted \(\FBE\), namely
\begin{equation}\label{eq:FBEu}
	\DRE(s)
{}={}
	\FBE(u),
\quad
	\text{where \(u=\prox_{\gamma\sDRS}(s)\).}
\end{equation}

