				\innprod{\nabla\sDRS(u^+)-\nabla\sDRS(u)}{v-u}
			\\
			{}={} &
				\DRE(s)
				{}-{}
				\rho(u,u^+)
				{}+{}
				\innprod{\nabla\sDRS(u^+)-\nabla\sDRS(u)}{v-u}
				{}+{}
				\tfrac{1}{2\gamma}
				\|u-u^+\|^2
				{}+{}
				\tfrac1\gamma
				\innprod{u^+-u}{u-v}.
			\end{align*}%
		}%
		Since
		\(
			u-v
		{}={}
