% 			\|u-u^+\|^2
% 		{}\geq{}
% 			\tfrac{1}{(1+\gamma L_{\sDRS})^2}
% 			\|s-s^+\|^2
% 		\]
		We now proceed by cases.
		\begin{proofitemize}
		\item\textbf{Case 1: \(\lambda\in(0,2)\).}

