% 				{}<{}
% 					\tfrac{\lambda}{2(1+p)}
% 				\quad\cup\quad &
% 					\tfrac{\lambda}{2(1+p)}
% 				{}\leq{}
% 					\xi
% 				{}<{}
% 					1,
% 				\end{align*}
% 				that is, \(\gamma L_{\sDRS}=\xi<1\).
				Since \(\sigma=-[\sigma_{\sDRS}]_-\) and
				\[
					\tfrac{2-\lambda}{2\lambda\gamma}
					{}+{}
					\tfrac{\sigma}{2(1+p)}
				{}\leq{}
					\tfrac{2-\lambda}{2\lambda\gamma}
					{}+{}
					\tfrac{L_{\sDRS}}{2}
					{}-{}
					\tfrac{\gamma L_{\sDRS}^2}{\lambda}
				\quad\Leftrightarrow\quad
					\gamma
				{}\leq{}
					\tfrac{\lambda}{2(L_{\sDRS}+\sigma)},
				\]
				from \eqref{eq:cbar} we conclude that \(c\) is as in \eqref{eq:DRE:SD}.
			%%%%
			%%%%
			%%%%
			\item\textbf{Case 1b:} \(2(1+\nicefrac{\sigma}{L_{\sDRS}})<\lambda<2\).

				Necessarily \(\sigma<0\), for otherwise the range of \(\lambda\) would be empty.
				In particular, \(\sigma=\sigma_{\sDRS}\), and the lower bound on \(\lambda\) can be expressed as
				\(
					\sigma_{\sDRS}<-\frac{2-\lambda}{2}L_{\sDRS}
				\).
				Consequently, \(L\coloneqq\tfrac{-2\sigma_{\sDRS}}{2-\lambda}\) is strictly larger than \(L_{\sDRS}\), and in particular \(\sigma+L=\sigma_{\sDRS}+L>0\).
				The ratio of \(\sigma\) and \(L\) is thus \(p=\tfrac\lambda2-1\), and \eqref{eq:c} becomes
				\begin{equation}\label{eq:c2}
					c
				{}={}
					\tfrac{2-\lambda}{2\lambda\gamma}
					{}+{}
					\begin{ifcases}
						\tfrac{\sigma_{\sDRS}}{\lambda}
					&
						\gamma
						{}<{}
						\tfrac{2-\lambda}{-2\sigma_{\sDRS}}
					\\[3pt]
						\tfrac{\sigma_{\sDRS}}{\lambda}-\tfrac{\gamma L_{\sDRS}^2}{\lambda}+\tfrac{2-\lambda}{-2\sigma_{\sDRS}\lambda}L_{\sDRS}^2
					\otherwise.
					\end{ifcases}
				\end{equation}
				Let us show that, when
				\(
					\gamma
				{}<{}
					\tfrac{2-\lambda}{-2\sigma_{\sDRS}}
				{}={}
					\tfrac1L
				\),
				also in this case the sufficient decrease constant \(c\) is strictly positive.
				We have
				\[
					\tfrac cL
				{}={}
					\tfrac{2-\lambda}{2\lambda\gamma L}
					{}+{}
					\tfrac{\sigma_{\sDRS}}{\lambda}
					\tfrac1L
				{}>{}
					\tfrac{2-\lambda}{2\lambda}
					{}+{}
					\tfrac{\sigma_{\sDRS}}{\lambda}
					\tfrac{2-\lambda}{-2\sigma_{\sDRS}}
				{}={}
					0,
				\]
				hence the claim.
				This concludes the proof for the case \(\lambda\in(0,2)\).
