		\item\textbf{Case 2: \(\lambda\geq2\).}

			\noindent
			In this case we need to assume that \(\sDRS\) is strongly convex, that is, that \(\sigma_{\sDRS}>0\).
			Instead of considering a single expression of \(\rho\), we will rather take a convex combination of those in \cref{thm:hypo:rho0,thm:hypo:rho1}, namely
			\[
				\rho(u,u^+)
			{}={}
				(1-\alpha)\tfrac{\sigma_{\sDRS}}{2}\|u-u^+\|^2
				{}+{}
				\alpha\tfrac{1}{2L_{\sDRS}}\|\nabla\sDRS(u)-\nabla\sDRS(u^+)\|^2
			\]
			for some \(\alpha\in[0,1]\) to be determined.
			\eqref{eq:DRE:SD0} then becomes
			\[
				\tfrac{
					\DRE(s)-\DRE(s^+)
				}{
					L_{\sDRS}
				}
			{}\geq{}
				\left(
					\tfrac{2-\lambda}{2\lambda\xi}
					{}+{}
					\tfrac{(1-\alpha)p}{2}
				\right)
				\|u-u^+\|^2
				{}+{}
				\tfrac{1}{L_{\sDRS}^2}
				\left(
					\tfrac{\alpha}{2}
					{}-{}
					\tfrac{\xi}{\lambda}
				\right)
				\|\nabla\sDRS(u)-\nabla\sDRS(u^+)\|^2,
			\]
			where \(\x\coloneqq\gamma L_{\sDRS}\) and \(p\coloneqq\nicefrac{\sigma_{\sDRS}}{L_{\sDRS}}\in(0,1]\).
			By restricting \(\xi\in(0,1)\), since \(\lambda\geq2\) one can take
			\(
				\alpha
			{}\coloneqq{}
				\nicefrac{2\xi}{\lambda}
			{}\in{}
				(0,1)
			\)
			to make the coefficient multiplying the gradient norm vanish.
			We then obtain
			\begin{equation}\label{eq:clambda2}
				\tfrac{c}{L_{\sDRS}}
			{}={}
				\tfrac{2-\lambda}{2\lambda\xi}
				{}+{}
				\tfrac{(\lambda-2\xi)p}{2\lambda}.
			\end{equation}
			Imposing \(c>0\) results in the following second-order equation in variable \(\xi\),
			\begin{equation}\label{eq:xi}
				2p\xi^2-p\lambda\xi+(\lambda-2)
			{}<{}
				0.
			\end{equation}
			The discriminant is
			\(
				\Delta
			{}\coloneqq{}
				(p\lambda)^2
				{}-{}
				8p(\lambda-2)
			\),
			which, for \(\lambda\geq2\), is strictly positive iff
			\[
				2
			{}\leq{}
				\lambda
			{}<{}
				\tfrac{4}{1+\sqrt{1-p}}
			~~\vee~~
				\lambda
			{}>{}
				\tfrac{4}{1-\sqrt{1-p}}.
			\]
			Denoting
			\(
				\delta
			{}\coloneqq{}
				\sqrt\Delta
			{}={}
				\sqrt{
					(p\lambda)^2
					{}-{}
					8p(\lambda-2)
				}
			\),
			the solution to \eqref{eq:xi} is
			\(
				\tfrac{
					p\lambda
					{}-{}
					\delta
				}{
					4p
				}
			{}<{}
				\x
			{}<{}
				\tfrac{
					p\lambda
					{}+{}
					\delta
				}{
					4p
				}
			\).
			However, the case \(\lambda\geq 4\) has to be discarded, as
			\(
				\tfrac{p\lambda-\delta}{4p}
			{}>{}
				1
			\)
			in this case, contradicting the fact that \(p\leq1\).
			To see this, suppose \(\lambda\geq4\).
			Then,
			\begin{align*}
				\tfrac{
					p\lambda
					{}-{}
					\delta
				}{
					4p
				}
			{}<{}
				1
			~~\Leftrightarrow~~ &
				p(\lambda-4)
			{}<{}
				\delta
			\\
			~~\Leftrightarrow~~ &
				p^2(\lambda-4)^2
			{}<{}
				\Delta
			{}={}
				(p\lambda)^2
				{}-{}
				8p(\lambda-2)
			\\
			~~\Leftrightarrow~~ &
				p(2-\lambda)
			{}<{}
				2-\lambda,
			\end{align*}
			hence \(p>1\), which contradicts the fact that \(\sigma_{\sDRS}\leq L_{\sDRS}\).
% 			Here and in the second implication we used the assumption \(\lambda\geq4\).
			Thus, the only feasible ranges are the ones given in \eqref{eq:lambda>=2}, hence the claimed sufficient decrease constant \(c\), cf. \eqref{eq:clambda2}.
			\qedhere
		\end{proofitemize}
% 		Also in this case, the claimed range of \(\gamma\) and value of \(c\) have been found.
	\end{proof}
\end{thm}

\begin{proof}
		To avoid trivialities, we assume that a fixed point is not found in a finite number of iterations, hence that \(v^k\neq u^k\) for all \(k\)'s.
		\begin{proofitemize}
		\item\ref{thm:DRS:r}
			Let \(c=c(\gamma,\lambda)\) be as in \cref{thm:DRE:SD}.
			Telescoping the inequality \eqref{eq:DRE:SD} yields
			\begin{align*}
			\textstyle
				\tfrac{c\lambda^2}{(1+\gamma L_{\sDRS})^2}
				\sum_{k\in\N}{
					\|u^k-v^k\|^2
				}
			{}\leq{} &
			\textstyle
				\sum_{k\in\N}{
				\bigl[
					\DRE(s^k)
					{}-{}
					\DRE(s^{k+1})
				\bigr]}
			{}\leq{}
				\DRE(s^0)-\inf\DRE.
			\end{align*}
			Since \(\inf\DRE=\inf\varphi>-\infty\) and \(\DRE\) is real valued (cf. \cref{thm:C0,thm:DREequiv}), it follows that \(\seq{u^k-v^k}\) is square summable, hence the claimed rate of convergence.
			Moreover, since \(\DRE(s^k)\) is decreasing it admits a (finite) limit, be it \(\varphi_\star\).
	%%%%%%%%
		\item\ref{thm:DRS:uv}
			Since \(\seq{u^k-v^k}\to 0\), necessarily \(\seq{u^k}\) and \(\seq{v^k}\) have same cluster points.
			Suppose that \(\seq{u^k}[k\in K]\to u'\) for some \(K\subseteq\N\) and \(u'\in\R^p\).
			Then, \(\seq{v^k}[k\in K]\to u'\), and since \(s^k=u^k+\nabla\sDRS(u^k)\) (cf. \cref{thm:proxfEquiv}), continuity of \(\nabla\sDRS\) implies that
			\(
				\seq{s^k}[k\in K]
			{}\to{}
				s'
			{}={}
				u'+\gamma\nabla\sDRS(u')
			\).
			From \cref{thm:proxfEquiv} we infer that \(u'=\prox_{\gamma\sDRS}(s')\).

			Similarly, \(\seq{\Fw{u^k}}[k\in K]\to \Fw{u'}\), and the outer semicontinuity of \(\prox_{\gamma\nsDRS}\) \cite[Ex. 5.23(b)]{rockafellar2011variational} combined with \eqref{eq:vFBS} implies that
			\[
				u'
			{}={}
				\lim_{K\ni k\to\infty}{
					\hspace*{-5pt}
					v^k
				}
			{}\in{}
				\limsup_{K\ni k\to\infty}{
					\FB{u^k}
				}
			{}\subseteq{}
				\FB{u'}.
			\]
			From \eqref{eq:prox:subdiff} we then have that
			\(
				-\nabla\sDRS(u')
			{}\in{}
				\hat\partial\nsDRS(u')
			\),
			hence \(0\in\hat\partial\varphi(u')\), as it follows from \cite[Ex. 8.8]{rockafellar2011variational}.
			Finally, since \(v^k\to u'\),
			\[
				\varphi(u')
			{}\leq{}
				\liminf_{K\ni k\to\infty}{
					\varphi(v^k)
				}
			{}\leq{}
				\limsup_{K\ni k\to\infty}{
					\varphi(v^k)
				}
			{}\leq{}
				\limsup_{K\ni k\to\infty}{
					\DRE(s^k)
				}
			{}={}
				\DRE(s')
			{}\leq{}
				\varphi(u'),
			\]
			where the first inequality is due to lower semicontinuity of \(\varphi\), the third and the last to the sandwiching property (\cref{thm:sandwich}), and the equality to the continuity of \(\DRE\) (\cref{thm:C0}).
			This shows that \(\seq{\varphi(u^k)}[k\in K]\to\varphi(u')=\DRE(s')\), and since \(\seq{\DRE(s^k)}\to\varphi_\star\), then necessarily \(\varphi(u')=\DRE(s')=\varphi_\star\) independently of the cluster point \(u'\).
			The last assert follows from the optimality condition of \(v^k\) as in \eqref{eq:vFBS}, namely,
			\(
				\tfrac1\gamma(u^k-v^k)
				{}-{}
				\nabla\sDRS(u^k)
			{}\in{}
				\hat\partial\nsDRS(v^k)
			\)
			due to \eqref{eq:prox:subdiff}, together with \(\sigma_{\sDRS}\)-hypoconvexity of \(\sDRS\).
		\item\ref{thm:DRS:bounded}.
			Suppose that \(\varphi\) has bounded level sets.
			Then, it follows from \cref{thm:boundedlev} that so does \(\DRE\), and since
			\(
				s^k
			{}\in{}
				\lev_{\leq\DRE(s^0)}\DRE
			\)
			for all \(k\in\N\), then the sequence \(\seq{s^k}\) is bounded.
			Due to Lipschitz continuity of \(\prox_{\gamma\sDRS}\) (cf. \cref{thm:proxfLip}), also \(\seq{u^k}\) is bounded.
			In turn, since \(v^k-u^k\to 0\) we conclude that also \(\seq{v^k}\) is bounded.
		\qedhere
		\end{proofitemize}
	\end{proof}

\begin{appendixproof}{thm:rho}%
	\begin{proofitemize}
	\item\ref{thm:hypo:rho0}.
		This is the lower bound in \eqref{eq:LipBound}.
	\item\ref{thm:hypo:rho1}.
		Let \(L\geq L_h\) and \(\sigma\in(-L,\min\set{0,\sigma_h}]\) be fixed.
		Then, \(h\) is \(L\)-smooth and \(\sigma\)-hypoconvex, and from \cite[Thm. 2.1.12]{nesterov2003introductory} we obtain that
		\begin{equation}\label{eq:LipBound:mix}
			\innprod{
				\nabla h(y)-\nabla h(x)
			}{
				y-x
			}
		{}\geq{}
			\tfrac{\sigma L}{L+\sigma}\|x-y\|^2
			{}+{}
			\tfrac{1}{L+\sigma}\|\nabla h(x)-\nabla h(y)\|^2
		\end{equation}
		for all \(x,y\in\R^n\).
		(Although \cite[Thm. 2.1.12]{nesterov2003introductory} assumes \(\sigma>0\), the given proof does not necessitate this restriction).
		Moreover, \(\psi\coloneqq h-\tfrac\sigma2\|{}\cdot{}\|^2\) is convex and \(L_\psi\)-smooth, with \(L_\psi=L-\sigma\).
		Consequently, for all \(x,y\in\R^n\) one has
		\(
			\psi(y)
		{}\geq{}
			\psi(x)
			{}+{}
			\innprod{\nabla\psi(x)}{y-x}
			{}+{}
			\tfrac{1}{2L_\psi}\|\nabla\psi(y)-\nabla\psi(x)\|^2
		\),
		see \cite[Thm. 2.1.5]{nesterov2003introductory}, resulting in
		\begin{align*}
			h(y)
		{}\geq{} &
			h(x)
			{}+{}
			\innprod{\nabla h(x)}{y-x}
			{}+{}
			\tfrac{\sigma L}{2(L-\sigma)}
			\|y-x\|^2
			{}+{}
			\tfrac{1}{2(L-\sigma)}
			\|\nabla h(y)-\nabla h(x)\|^2
		\\
		&
			{}-{}
			\tfrac{\sigma}{2(L-\sigma)}
			\innprod{
				\nabla h(y)-\nabla h(x)
			}{
				y-x
			}.
		\end{align*}
		Since \(\sigma\leq0\), the coefficient of the scalar product in the second line is positive.
		We may thus invoke the inequality \eqref{eq:LipBound:mix} to arrive to
		\begin{align*}
			h(y)
		{}\geq{} &
			h(x)
			{}+{}
			\innprod{\nabla h(x)}{y-x}
			{}+{}
			\tfrac{\sigma L}{2(L-\sigma)}
			\|y-x\|^2
			{}+{}
			\tfrac{1}{2(L-\sigma)}
			\|\nabla h(y)-\nabla h(x)\|^2
		\\
		&
			{}-{}
			\tfrac{\sigma}{2(L-\sigma)}
			\left[
				\tfrac{\sigma L}{L+\sigma}\|x-y\|^2
				{}+{}
				\tfrac{1}{L+\sigma}\|\nabla h(x)-\nabla h(y)\|^2
			\right]
		\\
		{}={} &
			h(x)
			{}+{}
			\innprod{\nabla h(x)}{y-x}
			{}+{}
			\tfrac{\sigma L}{2(L+\sigma)}
			\|y-x\|^2
			{}+{}
			\tfrac{1}{2(L+\sigma)}
			\|\nabla h(y)-\nabla h(x)\|^2,
		\end{align*}
		hence the claimed inequality.
	\qedhere
	\end{proofitemize}
\end{appendixproof}

\begin{appendixproof}{thm:proxf}%
	Let \(\gamma\in(0,\nicefrac{1}{[\sigma_h]_-})\) be fixed, and let \(\psi\coloneqq\gamma h+\tfrac12\|{}\cdot{}\|^2\).
	Observe that \(\psi\in\cont^{1,1}(\R^n)\) is \(L_\psi\)-smooth and \(\sigma_\psi\)-strongly convex, with \(L_\psi=1+\gamma L_h\) and \(\sigma_\psi=1+\gamma\sigma_h\).
	In particular, due to strong convexity \(\inf\psi>-\infty\), and by definition of prox-boundedness it then follows that \(\gamma_h\geq\nicefrac{1}{[\sigma_h]_-}\).
	\begin{proofitemize}
	\item\ref{thm:proxfEquiv}.
		Follows from \eqref{eq:prox:subdiff}, by observing that \(h+\tfrac{1}{2\gamma}\|{}\cdot{}-s\|^2\) is strongly convex, hence that a minimizer is characterized by stationarity.
	\item\ref{thm:proxfLip}.
		For \(s,s'\in\R^n\), let \(u=\prox_{\gamma h}(s)\) and \(u'=\prox_{\gamma h}(s')\).
		Then,
		\[
			\innprod{s-s'}{u-u'}
		{}={}
			\innprod{
				\nabla\psi(u)
				{}-{}
				\nabla\psi(u')
			}{u-u'}
		{}\geq{}
			\sigma_\psi
			\|u-u'\|^2
		{}={}
			(1+\gamma\sigma_h)
			\|u-u'\|^2,
		\]
		where the first equality was shown in \ref{thm:proxfEquiv} and the inequality follows from \eqref{eq:innprod}.
		By using the \(\frac{1}{L_\psi}\)-cocoercivity of \(\nabla\psi\) \cite[Thm. 2.1.10]{nesterov2003introductory}, also the claimed strong monotonicity follows.
		In turn, the Cauchy-Schwartz inequality on the inner product yields \eqref{eq:biLip}.
	\item\ref{thm:MoreaufC1}.
		From \cite[Ex. 10.32]{rockafellar2011variational} it follows that \(h^\gamma\) is strictly continuous and that
		\(
			\partial h^\gamma(s)
		{}\subseteq{}
			\tfrac1\gamma(s-\prox_{\gamma h}(s))
		\).
		Because of single valuedness of \(\prox_{\gamma h}\), by invoking \cite[Thm. 9.18]{rockafellar2011variational} we conclude that \(h^\gamma\) is everywhere differentiable with
		\(
			\nabla h^\gamma(s)
		{}={}
			\tfrac1\gamma(s-\prox_{\gamma h}(s))
		\).
% 		Moreover, \(u\) minimizes \(h+\tfrac{1}{2\gamma}\|{}\cdot{}-s\|^2\) and in particular \(\tfrac{1}{\gamma}(s-u)\in\partial h(u)\).
% 		Therefore,
% 		\(
% 			\nabla h(u)
% 		{}\overrel*{\eqref{eq:NablaProj}}{}
