\begin{thm}[Lower bounds for smooth functions]\label{thm:rho}%
	Let \(h\in C^{1,1}(\R^n)\) be \(L_h\)-smooth and \(\sigma_h\)-hypoconvex.
	Then, for all \(x,y\in\R^n\) it holds that
	\[
		h(y)
	{}\geq{}
		h(x)
		{}+{}
		\innprod{\nabla h(x)}{y-x}
		{}+{}
		\rho(y,x),
	\]
	where
	\begin{enumerate}
	\item\label{thm:hypo:rho0}%
		either~
		\(
			\rho(y,x)
		{}={}
			\tfrac{\sigma_h}{2}
			\|y-x\|^2
		\),
	\item\label{thm:hypo:rho1}%
		or~
		\(
			\rho(y,x)
		{}={}
			\tfrac{\sigma_hL_h}{2(L_h+\sigma_h)}
			\|y-x\|^2
			{}+{}
			\tfrac{1}{2(L_h+\sigma_h)}
			\|\nabla h(y)-\nabla h(x)\|^2
		\),~
		provided that~
		\(
			-L_h<\sigma_h\leq 0
		\).
	\end{enumerate}
	Clearly, all inequalities remain valid if one replaces \(L_h\) with any \(L\geq L_h\) and \(\sigma_h\) with any \(\sigma\in[-L,\sigma_h]\).
	\begin{proof}
		See \Cref{proof:thm:rho}.
	\end{proof}
\end{thm}

\begin{prop}[Proximal properties of smooth functions]\label{thm:proxf}%
	Let \(h\in \cont^{1,1}(\dom h)\) be \(L_h\)-smooth, hence \(\sigma_h\)-hypoconvex for some \(\sigma_h\in[-L_h,L_h]\).
	Then, \(h\) is prox-bounded with \(\gamma_{h}\geq\nicefrac{1}{[\sigma_{h}]_-}\) and for all \(\gamma<\nicefrac{1}{[\sigma_{h}]_-}\) the following hold:
	\begin{enumerate}
	\item\label{thm:proxfEquiv}
		\(\prox_{\gamma h}\) is single valued, and for all \(s\in\R^n\) it holds that \(u=\prox_{\gamma h}(s)\) iff
		\(
			s=u+\gamma\nabla h(u)
		\).
	\item\label{thm:proxfLip}
		\(\prox_{\gamma h}\) is \((\tfrac{1}{1+\gamma L_{h}})\)-strongly monotone and \((1+\gamma\sigma_h)\)-cocoercive, in the sense that
		\[
			\innprod{u-u'}{s-s'}
		{}\geq{}
			\tfrac{1}{1+\gamma L_h}
			\|s-s'\|^2
		\quad\text{and}\quad
			\innprod{u-u'}{s-s'}
		{}\geq{}
			(1+\gamma\sigma_h)
			\|u-u'\|^2
		\]
		for all \(s,s'\in\R^n\), where \(u=\prox_{\gamma h}(s)\) and \(u'=\prox_{\gamma h}(s')\).
		In particular,
		\begin{equation}\label{eq:biLip}
			\tfrac{1}{1+\gamma L_h}
			\|s-s'\|
		{}\leq{}
			\|u-u'\|
		{}\leq{}
			\tfrac{1}{1+\gamma\sigma_h}
			\|s-s'\|.
		\end{equation}
		Thus, \(\prox_{\gamma h}\) is a \(\tfrac{1}{1+\gamma\sigma_h}\)-Lipschitz and invertible mapping, and its inverse \(\id+\gamma\nabla h\) is \((1+\gamma L_h)\)-Lipschitz continuous.
	\item\label{thm:MoreaufC1}
		\(h^\gamma\in \cont^{1,1}(\R^n)\) is \(L_{h^\gamma}\)-smooth and \(\sigma_{h^\gamma}\)-hypoconvex, with
		\(
			L_{h^\gamma}
		{}={}
			\max\set{
				\tfrac{L_{h}}{1+\gamma L_{h}},~
				\tfrac{[\sigma_{h}]_-}{1+\gamma\sigma_{h}}
			}
		\)
		and
		\(
			\sigma_{h^\gamma}
		{}={}
			\tfrac{\sigma_{h}}{1+\gamma\sigma_{h}}
		\).
		Moreover,
		\(
			\nabla h^\gamma(s)
		{}={}
			\tfrac{1}{\gamma}(s-\prox_{\gamma h}(s))
		\)
		and
		\(
			\nabla h(\prox_{\gamma h}(s))
		{}={}
			\tfrac{1}{\gamma}\bigl(s-\prox_{\gamma h}(s)\bigr)
		\).
	\end{enumerate}
	\begin{proof}
		See \Cref{proof:thm:proxf}.
	\end{proof}
\end{prop}

\begin{prop}[Sandwiching property]\label{thm:sandwich}%
	Suppose that \Cref{ass:DRS} is satisfied.
	Let \(\gamma<\nicefrac{1}{L_{\sDRS}}\) be fixed, and consider \(u,v\) generated by one \ref{DRS} iteration starting from \(s\in\R^p\).
	Then,
	\begin{enumerate}
	\item\label{thm:DREleq}
		\(\DRE(s)\leq\varphi(u)\).
	\item\label{thm:DREgeq}
		\(
			\varphi(v)
		{}\leq{}
			\DRE(s)
			{}-{}
			\tfrac{1-\gamma L_{\sDRS}}{2\gamma}\|u-v\|^2
		\).
% 		\(
% 			\varphi(v)+\tfrac{1-\gamma L_{\sDRS}}{2\gamma}\|u-v\|^2
% 		{}\leq{}
% 			\DRE(s)
% 		{}\leq{}
% 			\varphi(v)+\tfrac{1-\gamma\sigma_{\sDRS}}{2\gamma}\|u-v\|^2
% 		\).
	\end{enumerate}
	\begin{proof}
		\ref{thm:DREleq} is easily inferred from definition \eqref{eq:DRE} by considering \(w=u\).
		Moreover, it follows from \cite[Prop. 4.3]{themelis2018forward} and the fact that \(v\in\FB u\), cf. \eqref{eq:vFBS}, that
		\(
			\varphi(v)
		{}\leq{}
			\FBE(u)
			{}-{}
			\tfrac{1-\gamma L_{\sDRS}}{2\gamma}\|u-v\|^2
		\).
		\ref{thm:DREgeq} then follows from \eqref{eq:FBEu}.
	\end{proof}
\end{prop}

\begin{thm}[Minimization and level-boundedness equivalence]\label{thm:DREequiv}%
	Suppose that \Cref{ass:DRS} is satisfied.
	For any \(\gamma<\nicefrac{1}{L_{\sDRS}}\) the following hold:
	\begin{enumerate}
	\item\label{thm:inf}%
		\(\inf\varphi=\inf\DRE\).
	\item\label{thm:argmin}%
		\(\argmin\varphi=\prox_{\gamma\sDRS}\bigl(\argmin\DRE\bigr)\).
	\item\label{thm:boundedlev}%
		\(\varphi\) is level bounded iff so is \(\DRE\).
	\end{enumerate}
	\begin{proof}
		It follows from \cite[Thm. 4.4]{themelis2018forward} that the FBE satisfies \(\inf\varphi=\inf\FBE\) and \(\argmin\varphi=\argmin\FBE\).
		The similar properties \ref{thm:inf} and \ref{thm:argmin} of the DRE then follow from the identity \(\DRE=\FBE\circ\prox_{\gamma\sDRS}\), cf. \eqref{eq:FBEu}, and the fact that \(\prox_{\gamma\sDRS}\) is invertible, as shown in \cref{thm:proxf}.

		We now show \ref{thm:boundedlev}.
		Denote
		\(
			\varphi_\star
		{}\coloneqq{}
			\inf\varphi
		{}={}
			\inf\DRE
		\),
		which is finite by assumption.
		\begin{proofitemize}
		\item
			Suppose that \(\DRE\) is level bounded, and let \(u\in\lev_{\leq\alpha}\varphi\) for some \(\alpha>\varphi_\star\).
			Then, \(s\coloneqq u+\gamma\nabla\sDRS(u)\) is such that \(\prox_{\gamma\sDRS}(s)=u\), as shown in \cref{thm:proxfEquiv}.
			Thus, from \cref{thm:sandwich} it follows that \(s\in\lev_{\leq\alpha}\DRE\).
			In particular,
			\(
				\lev_{\leq\alpha}\varphi
			{}\subseteq{}
				[I+\gamma\nabla\sDRS]
				(\lev_{\leq\alpha}\DRE),
			\)
			and since \(\I+\gamma\nabla\sDRS\) is Lipschitz continuous and \(\lev_{\leq\alpha}\DRE\) is bounded by assumption, it follows that \(\lev_{\leq\alpha}\varphi\) is also bounded.
		\item
			Suppose now that \(\DRE\) is not level bounded.
			Then, there exists \(\alpha>\varphi_\star\) together with a sequence \(\seq{s_k}\) satisfying
			\(
				s_k
			{}\in{}
				\lev_{\leq\alpha}\DRE
				{}\setminus{}
				\ball 0k
			\)
			for all \(k\in\N\).
			Let \(u_k\coloneqq\prox_{\gamma\sDRS}(s_k)\), so that \(s_k=u_k+\gamma\nabla\sDRS(u_k)\) (cf. \cref{thm:proxfEquiv}), and let \(v_k\in\FB{u_k}\).
			From \cref{thm:DREgeq} it then follows that \(v_k\in\lev_{\leq\alpha}\varphi\), and that
			\[
				\alpha
				{}-{}
				\varphi_\star
			{}\geq{}
				\DRE(s_k)
				{}-{}
				\varphi_\star
			{}\geq{}
				\DRE(s_k)
				{}-{}
				\varphi(v_k)
			{}\geq{}
				\tfrac{1-\gamma L_{\sDRS}}{2\gamma}
				\|u_k-v_k\|^2.
			\]
			Therefore,
			\(
				\|u_k-v_k\|^2
			{}\leq{}
				\tfrac{
					2\gamma(\alpha-\varphi_\star)
				}{
					1-\gamma L_{\sDRS}
				}
			\)
			and
			\begin{align*}
				\|v_k\|
			{}\geq{} &
				\|u_k-u_0\|
				{}-{}
				\|u_0\|
				{}-{}
				\|u_k-v_k\|
			\smash{{}\overrel[\geq]{\ref{thm:proxfLip}}{}}
				\tfrac{1}{1+\gamma L_{\sDRS}}
				\|s_k-s_0\|
				{}-{}
				\|u_0\|
				{}-{}
				\|u_k-v_k\|
			\\
			{}\geq{} &
				\tfrac{
					k-\|s_0\|
				}{
					1+\gamma L_{\sDRS}
				}
				{}-{}
				\|u_0\|
				{}-{}
				\sqrt{
					\tfrac{
						2\gamma(\alpha-\varphi_\star)
					}{
						1-\gamma L_{\sDRS}
					}
				}
			{}\to{}
				+\infty
			\quad\text{as \(k\to\infty\).}
			\end{align*}
			This shows that \(\lev_{\leq\alpha}\varphi\) is also unbounded.
			\qedhere
		\end{proofitemize}
	\end{proof}
\end{thm}

\begin{thm}[Sufficient decrease on the DRE]\label{thm:DRE:SD}%
	Suppose that \Cref{ass:DRS} is satisfied, and consider one \ref{DRS} update
	\(
		s
	{}\mapsto{}
		(u,v,s^+)
	\)
	for some stepsize
	\(
		\gamma
	{}<{}
		\min\set{
			\tfrac{2-\lambda}{2[\sigma_{\sDRS}]_-},\,
			\tfrac{1}{L_{\sDRS}}
		}
	\)
	and relaxation \(\lambda\in(0,2)\).
	Then,
	\begin{equation}\label{eq:DRE:SD}
		\DRE(s)-\DRE(s^+)
	{}\geq{}
		\tfrac{c}{(1+\gamma L_{\sDRS})^2}\,
		\|s-s^+\|^2,
	\end{equation}
	where, denoting \(p_{\sDRS}\coloneqq\nicefrac{\sigma_{\sDRS}}{L_{\sDRS}}\in[-1,1]\), \(c\) is a strictly positive constant defined as%
	\footnote{%
		A one-line expression for the constant is
		\(
			c
		{}={}
			\tfrac{2-\lambda}{2\lambda\gamma}
			{}-{}
			\min\set{
				\tfrac{[p_{\sDRS}]_-}{\lambda},~
				L_{\sDRS}\max\set{
					\tfrac{[\sigma_{\sDRS}]_-}{2(1-[p_{\sDRS}]_-)},\,
					\tfrac12-\tfrac{\gamma L_{\sDRS}}{\lambda}
				}
			}
		\).
	}
	\begin{equation}\label{eq:DRE:c0}
		c
	{}={}
		\frac{2-\lambda}{2\lambda\gamma}
		{}-{}
		\begin{ifcases}
			L_{\sDRS}\max\set{
				\tfrac{[p_{\sDRS}]_-}{2(1-[p_{\sDRS}]_-)},\,
				\tfrac12-\tfrac{\gamma L_{\sDRS}}{\lambda}
			}
		&
				p_{\sDRS}
			{}\geq{}
				\tfrac\lambda2-1
% 			0<\lambda<2(1-[p_{\sDRS}]_-),
		\\
			\tfrac{[\sigma_{\sDRS}]_-}{\lambda}
		\otherwise[otherwise.]
		\end{ifcases}
	\end{equation}
	If \(\sDRS\) is strongly convex, then \eqref{eq:DRE:SD} also holds for
	\begin{equation}\label{eq:lambda>=2}
		2
	{}\leq{}
		\lambda
	{}<{}
		\tfrac{4}{1+\sqrt{1-p_{\sDRS}}}
	\quad\text{and}\quad
		\tfrac{
			p_{\sDRS}\lambda
			{}-{}
			\delta
		}{
			4\sigma_{\sDRS}
		}
	{}<{}
		\gamma
	{}<{}
		\tfrac{
			p_{\sDRS}\lambda
			{}+{}
			\delta
		}{
			4\sigma_{\sDRS}
		},
	\end{equation}
	where
	\(
		\delta
	{}\coloneqq{}
		\sqrt{(p_{\sDRS}\lambda)^2-8p_{\sDRS}(\lambda-2)}
	\),
	in which case
	\begin{equation}\label{eq:DRE:c1}
		c
	{}={}
		\tfrac{2-\lambda}{2\lambda\gamma}
		{}+{}
		\tfrac{\sigma_{\sDRS}}{\lambda}
		(\tfrac12-\tfrac{\gamma L_{\sDRS}}{\lambda}).
	\end{equation}
	\begin{proof}
		\newcommand\x\xi%
		Let \((u^+,v^+)\) be generated by one \ref{DRS} iteration starting at \(s^+\).
		Then,
		\begin{align*}
			\DRE(s^+)
		{}={} &
			\min_{w\in\R^n}\set{
				\sDRS(u^+)
				{}+{}
				\nsDRS(w)
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{w-u^+}
				{}+{}
				\tfrac{1}{2\gamma}
				\|w-u^+\|^2
			}
		\end{align*}
		and the minimum is attained at \(w=v^+\).
		Therefore, letting \(\rho\) be as in \cref{thm:rho},
		{\mathtight[0.9]%
			\begin{align*}
				\DRE(s^+)
			{}\leq{} &
				\sDRS(u^+)
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u^+}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			{}={} &
				\smashunderbracket[0.5pt]{
					\sDRS(u^+)
					{}+{}
					\innprod{\nabla\sDRS(u^+)}{u-u^+}
				}{}
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			% 			\dueto{\cref{thm:rho}}
			{}\overrel[\leq]{\llap{\cref{thm:rho}}}{} &
				\smashoverbracket[0.5pt]{
					\sDRS(u)
					{}-{}
					\rho(u,u^+)
				}{}
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			{}={} &
				\sDRS(u)
				{}-{}
				\rho(u,u^+)
				{}+{}
				\innprod{\nabla\sDRS(u)}{v-u}
% 				\innprod{\nabla\sDRS(\fillwidthof[c]{u^+}{u})}{v-u}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			&
				{+{}}
				\innprod{\nabla\sDRS(u^+)-\nabla\sDRS(u)}{v-u}
			\\
			{}={} &
				\DRE(s)
				{}-{}
				\rho(u,u^+)
				{}+{}
				\innprod{\nabla\sDRS(u^+)-\nabla\sDRS(u)}{v-u}
				{}+{}
				\tfrac{1}{2\gamma}
				\|u-u^+\|^2
				{}+{}
				\tfrac1\gamma
				\innprod{u^+-u}{u-v}.
			\end{align*}%
		}%
		Since
		\(
			u-v
		{}={}
			\tfrac1\lambda(s-s^+)
		{}={}
			\tfrac1\lambda(u-u^+)
			{}+{}
			\tfrac\gamma\lambda(\nabla\sDRS(u)-\nabla\sDRS(u^+))
		\),
		as it follows from \cref{thm:proxfEquiv}, it all simplifies to
		\begin{equation}\label{eq:DRE:SD0}
			\DRE(s)
			{}-{}
			\DRE(s^+)
		{}\geq{}
			\tfrac{2-\lambda}{2\gamma\lambda}
			\|u-u^+\|^2
			{}-{}
			\tfrac\gamma\lambda
			\|\nabla\sDRS(u^+)-\nabla\sDRS(u)\|^2
			{}+{}
			\rho(u,u^+).
		\end{equation}
		It will suffice to show that
		\[
			\DRE(s)-\DRE(s^+)
		{}\geq{}
			c
			\|u-u^+\|^2;
