		inequality \eqref{eq:DRE:SD} will then follow from the \(\tfrac{1}{1+\gamma L_{\sDRS}}\)-strong monotonicity of \(\prox_{\gamma\sDRS}\), see \cref{thm:proxfLip}.
% 		\[
% 			\|u-u^+\|^2
% 		{}\geq{}
% 			\tfrac{1}{(1+\gamma L_{\sDRS})^2}
% 			\|s-s^+\|^2
% 		\]
		We now proceed by cases.
		\begin{proofitemize}
		\item\textbf{Case 1: \(\lambda\in(0,2)\).}

			\noindent
			Let \(\sigma\coloneqq-[\sigma_{\sDRS}]_-=\min\set{\sigma_{\sDRS},0}\) and \(L\geq L_{\sDRS}\) be such that \(L+\sigma>0\); the value of such an \(L\) will be fixed later.
			Then, \(\sigma\leq0\) and \(\sDRS\) is \(L\)-smooth and \(\sigma\)-hypoconvex.
			We may thus choose \(\rho(u,u^+)\) as in \cref{thm:hypo:rho1} with these values of \(L\) and \(\sigma\).
			Inequality \eqref{eq:DRE:SD0} then becomes
			\[
				\tfrac{\DRE(s)-\DRE(s^+)}{L}
			{}\geq{}
				\left(
					\tfrac{2-\lambda}{2\lambda\x}
					{}+{}
					\tfrac{p}{2(1+p)}
				\right)
				\|u^+-u\|^2
				{}+{}
				\tfrac{1}{L^2}
				\left(
					\tfrac{1}{2(1+p)}
					{}-{}
					\tfrac{\x}{\lambda}
				\right)
				\|\nabla\sDRS(u^+)-\nabla\sDRS(u)\|^2,
			\]
			where \(\x\coloneqq\gamma L\) and \(p\coloneqq\nicefrac\sigma L\in(-1,0]\).
			Since \(\nabla\sDRS\) is \(L_{\sDRS}\)-Lipschitz continuous, the claim holds provided that the constant
			\begin{equation}\label{eq:c}
				\frac cL
			{}={}
				\begin{ifcases}
					\tfrac{2-\lambda}{2\lambda\x}
					{}+{}
					\tfrac{p}{2(1+p)}
				&
					0
					{}<{}
					\tfrac{1}{2(1+p)}
					{}-{}
					\tfrac{\x}{\lambda}
				\\[3pt]
					\tfrac{2-\lambda}{2\lambda\x}
					{}+{}
					\tfrac{p}{2(1+p)}
					{}+{}
					\tfrac{L_{\sDRS}^2}{L^2}
					\left(
						\tfrac{1}{2(1+p)}
						{}-{}
						\tfrac{\x}{\lambda}
					\right)
				\otherwise[otherwise,]
				\end{ifcases}
			\end{equation}
			is strictly positive.
% 			
			Now, let us consider two subcases:
			\begin{itemize}
			\item\textbf{Case 1a:} \(0<\lambda\leq 2(1+\nicefrac{\sigma}{L_{\sDRS}})\).

				Then,
				\(
					\sigma\geq -\frac{2-\lambda}{2}L_{\sDRS}>-L_{\sDRS}
				\)
				and we can take \(L=L_{\sDRS}\).
				Consequently, \(p=\nicefrac{\sigma}{L_{\sDRS}}\), \(\x=\gamma L_{\sDRS}\), and \eqref{eq:c} becomes
				\begin{equation}\label{eq:cbar}
					\frac{c}{L_{\sDRS}}
				{}={}
					\frac{2-\lambda}{2\lambda\gamma L_{\sDRS}}
					{}+{}
					\begin{ifcases}
						\tfrac{p}{2(1+p)}
					&
						\gamma
						{}<{}
						\tfrac{\lambda}{2(1+p)}
					\\[3pt]
						\tfrac{1}{2}
						{}-{}
						\tfrac{\gamma L_{\sDRS}}{\lambda}
					\otherwise.
					\end{ifcases}
				\end{equation}
				Let us verify that in this case any \(\gamma\) such that \(\gamma<\nicefrac{1}{L_{\sDRS}}\) yields a strictly positive coefficient \(c\).
				If \(0<\gamma L_{\sDRS}<\frac{\lambda}{2(1+p)}\leq 1\), then
				\[
					\tfrac{c}{L_{\sDRS}}
				{}={}
					\tfrac{2-\lambda}{2\lambda\gamma L_{\sDRS}}
					{}+{}
					\tfrac{p}{2(1+p)}
				{}>{}
					\tfrac{2-\lambda}{2\lambda}
					{}+{}
					\tfrac{p}{\lambda}
				{}={}
					\tfrac{1+p}{\lambda}
					{}-{}
					\tfrac{1}{2}
				{}\geq{}
					0,
				\]
