\begin{thm}[Subsequential convergence]\label{thm:DRS}%
	Suppose that \Cref{ass:DRS} is satisfied, and consider a sequence \(\seq{s^k,u^k,v^k}\) generated by \ref{DRS} with stepsize \(\gamma\) and relaxation \(\lambda\) as in \Cref{thm:DRE:SD}, starting from \(s^0\in\R^p\).
	The following hold:%
	\begin{enumerate}
	\item\label{thm:DRS:r}
		The residual \(\seq{u^k-v^k}\) vanishes with rate
		\(
			\min_{i\leq k}\|u^i-v^i\|
		{}={}
			o(\nicefrac{1}{\sqrt k})
		\).
	\item\label{thm:DRS:uv}
		\(\seq{u^k}\) and \(\seq{v^k}\) have same cluster points, all of which are stationary for \(\varphi\) and on which \(\varphi\) has same value, this being the limit of \(\seq{\DRE(s^k)}\).
		In fact, for each \(k\) one has
		\(
			\dist(0,\hat\partial\varphi(v^k))
		{}\leq{}
			\frac{1-\gamma\sigma_{\sDRS}}{2\gamma}
			\|u^k-v^k\|
		\).
	\item\label{thm:DRS:bounded}
		If \(\varphi\) has bounded level sets, then the sequence \(\seq{s^k,u^k,v^k}\) is bounded.
	\end{enumerate}

\begin{proof}
		To avoid trivialities, we assume that a fixed point is not found in a finite number of iterations, hence that \(v^k\neq u^k\) for all \(k\)'s.
		\begin{proofitemize}
		\item\ref{thm:DRS:r}
			Let \(c=c(\gamma,\lambda)\) be as in \cref{thm:DRE:SD}.
			Telescoping the inequality \eqref{eq:DRE:SD} yields
			\begin{align*}
			\textstyle
				\tfrac{c\lambda^2}{(1+\gamma L_{\sDRS})^2}
				\sum_{k\in\N}{
					\|u^k-v^k\|^2
				}
			{}\leq{} &
			\textstyle
				\sum_{k\in\N}{
				\bigl[
					\DRE(s^k)
					{}-{}
					\DRE(s^{k+1})
				\bigr]}
			{}\leq{}
				\DRE(s^0)-\inf\DRE.
			\end{align*}
			Since \(\inf\DRE=\inf\varphi>-\infty\) and \(\DRE\) is real valued (cf. \cref{thm:C0,thm:DREequiv}), it follows that \(\seq{u^k-v^k}\) is square summable, hence the claimed rate of convergence.
			Moreover, since \(\DRE(s^k)\) is decreasing it admits a (finite) limit, be it \(\varphi_\star\).
	%%%%%%%%
		\item\ref{thm:DRS:uv}
			Since \(\seq{u^k-v^k}\to 0\), necessarily \(\seq{u^k}\) and \(\seq{v^k}\) have same cluster points.
			Suppose that \(\seq{u^k}[k\in K]\to u'\) for some \(K\subseteq\N\) and \(u'\in\R^p\).
			Then, \(\seq{v^k}[k\in K]\to u'\), and since \(s^k=u^k+\nabla\sDRS(u^k)\) (cf. \cref{thm:proxfEquiv}), continuity of \(\nabla\sDRS\) implies that
			\(
				\seq{s^k}[k\in K]
			{}\to{}
				s'
			{}={}
				u'+\gamma\nabla\sDRS(u')
			\).
			From \cref{thm:proxfEquiv} we infer that \(u'=\prox_{\gamma\sDRS}(s')\).

			Similarly, \(\seq{\Fw{u^k}}[k\in K]\to \Fw{u'}\), and the outer semicontinuity of \(\prox_{\gamma\nsDRS}\) \cite[Ex. 5.23(b)]{rockafellar2011variational} combined with \eqref{eq:vFBS} implies that
			\[
				u'
			{}={}
				\lim_{K\ni k\to\infty}{
					\hspace*{-5pt}
					v^k
				}
			{}\in{}
				\limsup_{K\ni k\to\infty}{
					\FB{u^k}
				}
			{}\subseteq{}
				\FB{u'}.
			\]
			From \eqref{eq:prox:subdiff} we then have that
			\(
				-\nabla\sDRS(u')
			{}\in{}
				\hat\partial\nsDRS(u')
			\),
			hence \(0\in\hat\partial\varphi(u')\), as it follows from \cite[Ex. 8.8]{rockafellar2011variational}.
			Finally, since \(v^k\to u'\),
			\[
				\varphi(u')
			{}\leq{}
				\liminf_{K\ni k\to\infty}{
					\varphi(v^k)
				}
			{}\leq{}
				\limsup_{K\ni k\to\infty}{
					\varphi(v^k)
				}
			{}\leq{}
				\limsup_{K\ni k\to\infty}{
					\DRE(s^k)
				}
			{}={}
				\DRE(s')
			{}\leq{}
				\varphi(u'),
			\]
			where the first inequality is due to lower semicontinuity of \(\varphi\), the third and the last to the sandwiching property (\cref{thm:sandwich}), and the equality to the continuity of \(\DRE\) (\cref{thm:C0}).
			This shows that \(\seq{\varphi(u^k)}[k\in K]\to\varphi(u')=\DRE(s')\), and since \(\seq{\DRE(s^k)}\to\varphi_\star\), then necessarily \(\varphi(u')=\DRE(s')=\varphi_\star\) independently of the cluster point \(u'\).
			The last assert follows from the optimality condition of \(v^k\) as in \eqref{eq:vFBS}, namely,
			\(
				\tfrac1\gamma(u^k-v^k)
				{}-{}
				\nabla\sDRS(u^k)
			{}\in{}
				\hat\partial\nsDRS(v^k)
			\)
			due to \eqref{eq:prox:subdiff}, together with \(\sigma_{\sDRS}\)-hypoconvexity of \(\sDRS\).
		\item\ref{thm:DRS:bounded}.
			Suppose that \(\varphi\) has bounded level sets.
			Then, it follows from \cref{thm:boundedlev} that so does \(\DRE\), and since
			\(
				s^k
			{}\in{}
				\lev_{\leq\DRE(s^0)}\DRE
			\)
			for all \(k\in\N\), then the sequence \(\seq{s^k}\) is bounded.
			Due to Lipschitz continuity of \(\prox_{\gamma\sDRS}\) (cf. \cref{thm:proxfLip}), also \(\seq{u^k}\) is bounded.
			In turn, since \(v^k-u^k\to 0\) we conclude that also \(\seq{v^k}\) is bounded.
		\qedhere
		\end{proofitemize}
	\end{proof}

\begin{proof}
		To avoid trivialities, we assume that a fixed point is not found in a finite number of iterations, hence that \(v^k\neq u^k\) for all \(k\)'s.
		\begin{proofitemize}

\item\ref{thm:DRS:r}
	Let \(c=c(\gamma,\lambda)\) be as in \cref{thm:DRE:SD}.
	Telescoping the inequality \eqref{eq:DRE:SD} yields
	\begin{align*}
	\textstyle
		\tfrac{c\lambda^2}{(1+\gamma L_{\sDRS})^2}
		\sum_{k\in\N}{
			\|u^k-v^k\|^2
		}
	{}\leq{} &
	\textstyle
		\sum_{k\in\N}{
		\bigl[
			\DRE(s^k)
			{}-{}
			\DRE(s^{k+1})
		\bigr]}
	{}\leq{}
		\DRE(s^0)-\inf\DRE.
	\end{align*}
	Since \(\inf\DRE=\inf\varphi>-\infty\) and \(\DRE\) is real valued (cf. \cref{thm:C0,thm:DREequiv}), it follows that \(\seq{u^k-v^k}\) is square summable, hence the claimed rate of convergence.


Similarly, \(\seq{\Fw{u^k}}[k\in K]\to \Fw{u'}\), and the outer semicontinuity of \(\prox_{\gamma\nsDRS}\) \cite[Ex. 5.23(b)]{rockafellar2011variational} combined with \eqref{eq:vFBS} implies that
\[
	u'
{}={}
	\lim_{K\ni k\to\infty}{
		\hspace*{-5pt}
		v^k
	}
{}\in{}
	\limsup_{K\ni k\to\infty}{
		\FB{u^k}
	}
{}\subseteq{}
	\FB{u'}.
\]

Finally, since \(v^k\to u'\),
\[
	\varphi(u')
{}\leq{}
	\liminf_{K\ni k\to\infty}{
		\varphi(v^k)
	}
{}\leq{}
	\limsup_{K\ni k\to\infty}{
		\varphi(v^k)
	}
{}\leq{}
	\limsup_{K\ni k\to\infty}{
		\DRE(s^k)
	}
{}={}
	\DRE(s')
{}\leq{}
	\varphi(u'),
\]
where the first inequality is due to lower semicontinuity of \(\varphi\), the third and the last to the sandwiching property (\cref{thm:sandwich}), and the equality to the continuity of \(\DRE\) (\cref{thm:C0}).
This shows that \(\seq{\varphi(u^k)}[k\in K]\to\varphi(u')=\DRE(s')\), and since \(\seq{\DRE(s^k)}\to\varphi_\star\), then necessarily \(\varphi(u')=\DRE(s')=\varphi_\star\) independently of the cluster point \(u'\).

\begin{equation}\label{eq:P}
	\minimize_{s\in\R^p} \varphi(s)\equiv\sDRS(s)+\nsDRS(s).
\end{equation}

			The class of functions \(\func{h}{\R^n}{\R}\) that are \(k\) times continuously differentiable is denoted as \(\cont^k(\R^n)\).
We write \(h\in\cont^{1,1}(\R^n)\) to indicate that \(h\in\cont^1(\R^n)\) and that \(\nabla h\) is Lipschitz continuous with modulus \(L_h\).
To simplify the terminology, we will say that such an \(h\) is \DEF{\(L_h\)-smooth}.
It follows from \cite[Prop. A.24]{bertsekas2016nonlinear} that if \(h\) is \(L_h\)-smooth, then
\(
	|h(y)-h(x)-\innprod{\nabla h(x)}{y-x}|
{}\leq{}
	\tfrac{L_h}{2}\|y-x\|^2
\)
for all \(x,y\in\R^n\).
In particular, there exists \(\sigma_h\in[-L_h,L_h]\) such that \(h\) is \DEF{\(\sigma_h\)-hypoconvex}, in the sense that \(h-\tfrac{\sigma_h}{2}\|{}\cdot{}\|^2\) is a convex function.
Thus, every \(L_h\)-smooth and \(\sigma_h\)-hypoconvex function \(h\) satisfies
\begin{equation}\label{eq:LipBound}
	\tfrac{\sigma_h}{2}
	\|y-x\|^2
{}\leq{}
	h(y)-h(x)-\innprod{\nabla h(x)}{y-x}
{}\leq{}
	\tfrac{L_h}{2}
	\|y-x\|^2
\quad
	\forall x,y\in\R^n.
\end{equation}
By applying \cite[Thm. 2.1.5]{nesterov2003introductory} to the (convex) function \(\psi=h-\tfrac\sigma2\|{}\cdot{}\|^2\) we obtain that this is equivalent to having
\begin{equation}\label{eq:innprod}
	\sigma_h
	\|y-x\|^2
{}\leq{}
	\innprod{\nabla h(y)-\nabla h(x)}{y-x}
{}\leq{}
	L_h
	\|y-x\|^2
\quad
	\forall x,y\in\R^n.
\end{equation}
Note that \(\sigma\)-hypoconvexity generalizes the notion of (strong) convexity by allowing negative strong convexity moduli.
In fact, if \(\sigma=0\) then \(\sigma\)-hypoconvexity reduces to convexity, while for \(\sigma>0\) it denotes \(\sigma\)-strong convexity.

			The \DEF{proximal mapping} of \(\func{h}{\R^n}{\Rinf}\) with parameter \(\gamma>0\) is \(\ffunc{\prox_{\gamma h}}{\R^n}{\dom h}\) defined as
\begin{equation}
	\prox_{\gamma h}(x)
{}\coloneqq{}
	\argmin_{w\in\R^n}\set{
		h(w) + \tfrac{1}{2\gamma}\|w-x\|^2
	}.
\end{equation}
We say that a function \(h\) is \DEF{prox-bounded} if \(h+\tfrac{1}{2\gamma}\|{}\cdot{}\|^2\) is lower bounded for some \(\gamma>0\).
The supremum of all such \(\gamma\)
% --- which is possibly infinite, as it is the case when \(h\) is lower bounded or convex ---
is the \emph{threshold of prox-boundedness of \(h\)}, denoted as \(\gamma_h\).
If \(h\) is lsc, then \(\prox_{\gamma h}\) is nonempty- and compact-valued over \(\R^n\) for all \(\gamma\in(0,\gamma_h)\) \cite[Thm. 1.25]{rockafellar2011variational}.
Consequently, the value function of the minimization problem defining the proximal mapping, namely the \DEF{Moreau envelope} with stepsize \(\gamma\in(0,\gamma_h)\), denoted by \(\func{h^\gamma}{\R^n}{\R}\) and defined as
\begin{equation}
	\fillwidthof[r]{
		\prox_{\gamma h}(x)
	}{
		h^\gamma(x)
	}
{}\coloneqq{}
	\fillwidthof[l]{
		\argmin_{w\in\R^n}\set{
			h(w) + \tfrac{1}{2\gamma}\|w-x\|^2
		}.
	}{
		\inf_{w\in\R^n}\set{
			h(w) + \tfrac{1}{2\gamma}\|w-x\|^2
		},
	}
\end{equation}
is everywhere finite and, in fact, strictly continuous \cite[Ex. 10.32]{rockafellar2011variational}.
Moreover, the necessary optimality conditions of the problem defining \(\prox_{\gamma g}\) together with \cite[Thm. 10.1 and Ex. 8.8]{rockafellar2011variational} imply that
\begin{equation}\label{eq:prox:subdiff}
	\tfrac1\gamma(x-\bar x)
{}\in{}
	\hat\partial h(\bar x)
\quad
	\forall\bar x\in\prox_{\gamma h}(x).
\end{equation}

Starting from \(s\in\R^p\), let us consider variables \((u,v)\) generated by a \ref{DRS} step under \Cref{ass:DRS}.
As first noted in \cite{patrinos2014douglas}, from the relation \(s=u+\gamma\nabla\sDRS(u)\) (see \cref{thm:proxfEquiv}) it follows that
\begin{equation}\label{eq:vFBS}
	v\in\FB u
\end{equation}
is the result of a \DEF{forward-backward step} at \(u\), amounting to
\begin{align}\label{eq:DRSv}
	v
{}\in{}
	\argmin_{w\in\R^p}{} &
	\set{
		\nsDRS(w)
		{}+{}
		\smashunderbracket{
			\sDRS(u)
			{}+{}
			\innprod{\nabla\sDRS(u)}{w-u}
			{}+{}
			\tfrac{1}{2\gamma}\|w-u\|^2
		}{}
	},
\shortintertext{%
	see \eg \cite{bolte2014proximal,themelis2018forward} for an extensive discussion on nonconvex forward-backward splitting (FBS).
	This shows that \(v\) is the result of the minimization of a \emph{majorization model} for the original function \(\varphi=\sDRS+\nsDRS\), where the smooth function \(\sDRS\) is replaced by the quadratic upper bound emphasized by the under-bracket in \eqref{eq:DRSv}.
	First introduced in \cite{patrinos2014douglas} for convex problems, the \DEF{Douglas-Rachford envelope} (DRE) is the function \(\func{\DRE}{\R^n}{\R}\) defined as%
}
\label{eq:DRE}
	\DRE(s)
{}\coloneqq{}
	\min_{w\in\R^p}{} &
	\set{
		\nsDRS(w)
		{}+{}
		\sDRS(u)
		{}+{}
		\innprod{\nabla\sDRS(u)}{w-u}
		{}+{}
		\tfrac{1}{2\gamma}\|w-u\|^2
	}.
\end{align}

The expression \eqref{eq:DRE} emphasizes the close connection that the DRE has with the \DEF{forward-backward envelope} (FBE) as in \cite{themelis2018forward}, here denoted \(\FBE\), namely
\begin{equation}\label{eq:FBEu}
	\DRE(s)
{}={}
	\FBE(u),
\quad
	\text{where \(u=\prox_{\gamma\sDRS}(s)\).}
\end{equation}

\begin{thm}[Lower bounds for smooth functions]\label{thm:rho}%
	Let \(h\in C^{1,1}(\R^n)\) be \(L_h\)-smooth and \(\sigma_h\)-hypoconvex.
	Then, for all \(x,y\in\R^n\) it holds that
	\[
		h(y)
	{}\geq{}
		h(x)
		{}+{}
		\innprod{\nabla h(x)}{y-x}
		{}+{}
		\rho(y,x),
	\]
	where
	\begin{enumerate}
	\item\label{thm:hypo:rho0}%
		either~
		\(
			\rho(y,x)
		{}={}
			\tfrac{\sigma_h}{2}
			\|y-x\|^2
		\),
	\item\label{thm:hypo:rho1}%
		or~
		\(
			\rho(y,x)
		{}={}
			\tfrac{\sigma_hL_h}{2(L_h+\sigma_h)}
			\|y-x\|^2
			{}+{}
			\tfrac{1}{2(L_h+\sigma_h)}
			\|\nabla h(y)-\nabla h(x)\|^2
		\),~
		provided that~
		\(
			-L_h<\sigma_h\leq 0
		\).
	\end{enumerate}
	Clearly, all inequalities remain valid if one replaces \(L_h\) with any \(L\geq L_h\) and \(\sigma_h\) with any \(\sigma\in[-L,\sigma_h]\).

\begin{proof}
		See \Cref{proof:thm:rho}.
	\end{proof}

\begin{appendixproof}{thm:rho}%
	\begin{proofitemize}
	\item\ref{thm:hypo:rho0}.
		This is the lower bound in \eqref{eq:LipBound}.
	\item\ref{thm:hypo:rho1}.
		Let \(L\geq L_h\) and \(\sigma\in(-L,\min\set{0,\sigma_h}]\) be fixed.
		Then, \(h\) is \(L\)-smooth and \(\sigma\)-hypoconvex, and from \cite[Thm. 2.1.12]{nesterov2003introductory} we obtain that
		\begin{equation}\label{eq:LipBound:mix}
			\innprod{
				\nabla h(y)-\nabla h(x)
			}{
				y-x
			}
		{}\geq{}
			\tfrac{\sigma L}{L+\sigma}\|x-y\|^2
			{}+{}
			\tfrac{1}{L+\sigma}\|\nabla h(x)-\nabla h(y)\|^2
		\end{equation}
		for all \(x,y\in\R^n\).
		(Although \cite[Thm. 2.1.12]{nesterov2003introductory} assumes \(\sigma>0\), the given proof does not necessitate this restriction).
		Moreover, \(\psi\coloneqq h-\tfrac\sigma2\|{}\cdot{}\|^2\) is convex and \(L_\psi\)-smooth, with \(L_\psi=L-\sigma\).
		Consequently, for all \(x,y\in\R^n\) one has
		\(
			\psi(y)
		{}\geq{}
			\psi(x)
			{}+{}
			\innprod{\nabla\psi(x)}{y-x}
			{}+{}
			\tfrac{1}{2L_\psi}\|\nabla\psi(y)-\nabla\psi(x)\|^2
		\),
		see \cite[Thm. 2.1.5]{nesterov2003introductory}, resulting in
		\begin{align*}
			h(y)
		{}\geq{} &
			h(x)
			{}+{}
			\innprod{\nabla h(x)}{y-x}
			{}+{}
			\tfrac{\sigma L}{2(L-\sigma)}
			\|y-x\|^2
			{}+{}
			\tfrac{1}{2(L-\sigma)}
			\|\nabla h(y)-\nabla h(x)\|^2
		\\
		&
			{}-{}
			\tfrac{\sigma}{2(L-\sigma)}
			\innprod{
				\nabla h(y)-\nabla h(x)
			}{
				y-x
			}.
		\end{align*}
		Since \(\sigma\leq0\), the coefficient of the scalar product in the second line is positive.
		We may thus invoke the inequality \eqref{eq:LipBound:mix} to arrive to
		\begin{align*}
			h(y)
		{}\geq{} &
			h(x)
			{}+{}
			\innprod{\nabla h(x)}{y-x}
			{}+{}
			\tfrac{\sigma L}{2(L-\sigma)}
			\|y-x\|^2
			{}+{}
			\tfrac{1}{2(L-\sigma)}
			\|\nabla h(y)-\nabla h(x)\|^2
		\\
		&
			{}-{}
			\tfrac{\sigma}{2(L-\sigma)}
			\left[
				\tfrac{\sigma L}{L+\sigma}\|x-y\|^2
				{}+{}
				\tfrac{1}{L+\sigma}\|\nabla h(x)-\nabla h(y)\|^2
			\right]
		\\
		{}={} &
			h(x)
			{}+{}
			\innprod{\nabla h(x)}{y-x}
			{}+{}
			\tfrac{\sigma L}{2(L+\sigma)}
			\|y-x\|^2
			{}+{}
			\tfrac{1}{2(L+\sigma)}
			\|\nabla h(y)-\nabla h(x)\|^2,
		\end{align*}
		hence the claimed inequality.
	\qedhere
	\end{proofitemize}
\end{appendixproof}

