\begin{prop}[Sandwiching property]\label{thm:sandwich}%
	Suppose that \Cref{ass:DRS} is satisfied.
	Let \(\gamma<\nicefrac{1}{L_{\sDRS}}\) be fixed, and consider \(u,v\) generated by one \ref{DRS} iteration starting from \(s\in\R^p\).
	Then,
	\begin{enumerate}
	\item\label{thm:DREleq}
		\(\DRE(s)\leq\varphi(u)\).
	\item\label{thm:DREgeq}
		\(
			\varphi(v)
		{}\leq{}
			\DRE(s)
			{}-{}
			\tfrac{1-\gamma L_{\sDRS}}{2\gamma}\|u-v\|^2
		\).
% 		\(
% 			\varphi(v)+\tfrac{1-\gamma L_{\sDRS}}{2\gamma}\|u-v\|^2
% 		{}\leq{}
% 			\DRE(s)
% 		{}\leq{}
% 			\varphi(v)+\tfrac{1-\gamma\sigma_{\sDRS}}{2\gamma}\|u-v\|^2
% 		\).
	\end{enumerate}

\begin{proof}
		\ref{thm:DREleq} is easily inferred from definition \eqref{eq:DRE} by considering \(w=u\).
		Moreover, it follows from \cite[Prop. 4.3]{themelis2018forward} and the fact that \(v\in\FB u\), cf. \eqref{eq:vFBS}, that
		\(
			\varphi(v)
		{}\leq{}
			\FBE(u)
			{}-{}
			\tfrac{1-\gamma L_{\sDRS}}{2\gamma}\|u-v\|^2
		\).
		\ref{thm:DREgeq} then follows from \eqref{eq:FBEu}.
	\end{proof}

	Moreover, it follows from \cite[Prop. 4.3]{themelis2018forward} and the fact that \(v\in\FB u\), cf. \eqref{eq:vFBS}, that
	\(
		\varphi(v)
	{}\leq{}
		\FBE(u)
		{}-{}
		\tfrac{1-\gamma L_{\sDRS}}{2\gamma}\|u-v\|^2
	\).
	\ref{thm:DREgeq} then follows from \eqref{eq:FBEu}.
\end{proof}

\begin{proof}
		It follows from \cite[Thm. 4.4]{themelis2018forward} that the FBE satisfies \(\inf\varphi=\inf\FBE\) and \(\argmin\varphi=\argmin\FBE\).
		The similar properties \ref{thm:inf} and \ref{thm:argmin} of the DRE then follow from the identity \(\DRE=\FBE\circ\prox_{\gamma\sDRS}\), cf. \eqref{eq:FBEu}, and the fact that \(\prox_{\gamma\sDRS}\) is invertible, as shown in \cref{thm:proxf}.

		We now show \ref{thm:boundedlev}.
		Denote
		\(
			\varphi_\star
		{}\coloneqq{}
			\inf\varphi
		{}={}
			\inf\DRE
		\),
		which is finite by assumption.
		\begin{proofitemize}
		\item
			Suppose that \(\DRE\) is level bounded, and let \(u\in\lev_{\leq\alpha}\varphi\) for some \(\alpha>\varphi_\star\).
			Then, \(s\coloneqq u+\gamma\nabla\sDRS(u)\) is such that \(\prox_{\gamma\sDRS}(s)=u\), as shown in \cref{thm:proxfEquiv}.
			Thus, from \cref{thm:sandwich} it follows that \(s\in\lev_{\leq\alpha}\DRE\).
			In particular,
			\(
				\lev_{\leq\alpha}\varphi
			{}\subseteq{}
				[I+\gamma\nabla\sDRS]
				(\lev_{\leq\alpha}\DRE),
			\)
			and since \(\I+\gamma\nabla\sDRS\) is Lipschitz continuous and \(\lev_{\leq\alpha}\DRE\) is bounded by assumption, it follows that \(\lev_{\leq\alpha}\varphi\) is also bounded.
		\item
			Suppose now that \(\DRE\) is not level bounded.
			Then, there exists \(\alpha>\varphi_\star\) together with a sequence \(\seq{s_k}\) satisfying
			\(
				s_k
			{}\in{}
				\lev_{\leq\alpha}\DRE
				{}\setminus{}
				\ball 0k
			\)
			for all \(k\in\N\).
			Let \(u_k\coloneqq\prox_{\gamma\sDRS}(s_k)\), so that \(s_k=u_k+\gamma\nabla\sDRS(u_k)\) (cf. \cref{thm:proxfEquiv}), and let \(v_k\in\FB{u_k}\).
			From \cref{thm:DREgeq} it then follows that \(v_k\in\lev_{\leq\alpha}\varphi\), and that
			\[
				\alpha
				{}-{}
				\varphi_\star
			{}\geq{}
				\DRE(s_k)
				{}-{}
				\varphi_\star
			{}\geq{}
				\DRE(s_k)
				{}-{}
				\varphi(v_k)
			{}\geq{}
				\tfrac{1-\gamma L_{\sDRS}}{2\gamma}
				\|u_k-v_k\|^2.
			\]
			Therefore,
			\(
				\|u_k-v_k\|^2
			{}\leq{}
				\tfrac{
					2\gamma(\alpha-\varphi_\star)
				}{
					1-\gamma L_{\sDRS}
				}
			\)
			and
			\begin{align*}
				\|v_k\|
			{}\geq{} &
				\|u_k-u_0\|
				{}-{}
				\|u_0\|
				{}-{}
				\|u_k-v_k\|
			\smash{{}\overrel[\geq]{\ref{thm:proxfLip}}{}}
				\tfrac{1}{1+\gamma L_{\sDRS}}
				\|s_k-s_0\|
				{}-{}
				\|u_0\|
				{}-{}
				\|u_k-v_k\|
			\\
			{}\geq{} &
				\tfrac{
					k-\|s_0\|
				}{
					1+\gamma L_{\sDRS}
				}
				{}-{}
				\|u_0\|
				{}-{}
				\sqrt{
					\tfrac{
						2\gamma(\alpha-\varphi_\star)
					}{
						1-\gamma L_{\sDRS}
					}
				}
			{}\to{}
				+\infty
			\quad\text{as \(k\to\infty\).}
			\end{align*}
			This shows that \(\lev_{\leq\alpha}\varphi\) is also unbounded.
			\qedhere
		\end{proofitemize}
	\end{proof}

\begin{proof}
		It follows from \cite[Thm. 4.4]{themelis2018forward} that the FBE satisfies \(\inf\varphi=\inf\FBE\) and \(\argmin\varphi=\argmin\FBE\).
		The similar properties \ref{thm:inf} and \ref{thm:argmin} of the DRE then follow from the identity \(\DRE=\FBE\circ\prox_{\gamma\sDRS}\), cf. \eqref{eq:FBEu}, and the fact that \(\prox_{\gamma\sDRS}\) is invertible, as shown in \cref{thm:proxf}.

\item
	Suppose now that \(\DRE\) is not level bounded.
