			}{
				1+\gamma L_{\sDRS}
			}
			{}-{}
			\|u_0\|
			{}-{}
			\sqrt{
				\tfrac{
					2\gamma(\alpha-\varphi_\star)
				}{
					1-\gamma L_{\sDRS}
				}
			}
