\end{proof}

\begin{thm}[Sufficient decrease on the DRE]\label{thm:DRE:SD}%
	Suppose that \Cref{ass:DRS} is satisfied, and consider one \ref{DRS} update
	\(
		s
	{}\mapsto{}
		(u,v,s^+)
	\)
	for some stepsize
	\(
		\gamma
	{}<{}
		\min\set{
			\tfrac{2-\lambda}{2[\sigma_{\sDRS}]_-},\,
			\tfrac{1}{L_{\sDRS}}
		}
	\)
	and relaxation \(\lambda\in(0,2)\).
	Then,
	\begin{equation}\label{eq:DRE:SD}
		\DRE(s)-\DRE(s^+)
	{}\geq{}
		\tfrac{c}{(1+\gamma L_{\sDRS})^2}\,
		\|s-s^+\|^2,
	\end{equation}
	where, denoting \(p_{\sDRS}\coloneqq\nicefrac{\sigma_{\sDRS}}{L_{\sDRS}}\in[-1,1]\), \(c\) is a strictly positive constant defined as%
	\footnote{%
		A one-line expression for the constant is
		\(
			c
		{}={}
			\tfrac{2-\lambda}{2\lambda\gamma}
			{}-{}
			\min\set{
				\tfrac{[p_{\sDRS}]_-}{\lambda},~
				L_{\sDRS}\max\set{
					\tfrac{[\sigma_{\sDRS}]_-}{2(1-[p_{\sDRS}]_-)},\,
					\tfrac12-\tfrac{\gamma L_{\sDRS}}{\lambda}
				}
			}
		\).
	}
	\begin{equation}\label{eq:DRE:c0}
		c
	{}={}
		\frac{2-\lambda}{2\lambda\gamma}
		{}-{}
		\begin{ifcases}
			L_{\sDRS}\max\set{
				\tfrac{[p_{\sDRS}]_-}{2(1-[p_{\sDRS}]_-)},\,
				\tfrac12-\tfrac{\gamma L_{\sDRS}}{\lambda}
			}
		&
				p_{\sDRS}
			{}\geq{}
				\tfrac\lambda2-1
% 			0<\lambda<2(1-[p_{\sDRS}]_-),
		\\
			\tfrac{[\sigma_{\sDRS}]_-}{\lambda}
		\otherwise[otherwise.]
		\end{ifcases}
	\end{equation}
	If \(\sDRS\) is strongly convex, then \eqref{eq:DRE:SD} also holds for
	\begin{equation}\label{eq:lambda>=2}
		2
	{}\leq{}
		\lambda
	{}<{}
		\tfrac{4}{1+\sqrt{1-p_{\sDRS}}}
	\quad\text{and}\quad
		\tfrac{
			p_{\sDRS}\lambda
			{}-{}
			\delta
		}{
			4\sigma_{\sDRS}
		}
	{}<{}
		\gamma
	{}<{}
		\tfrac{
			p_{\sDRS}\lambda
			{}+{}
			\delta
		}{
			4\sigma_{\sDRS}
		},
	\end{equation}
	where
	\(
		\delta
	{}\coloneqq{}
		\sqrt{(p_{\sDRS}\lambda)^2-8p_{\sDRS}(\lambda-2)}
	\),
	in which case
	\begin{equation}\label{eq:DRE:c1}
		c
	{}={}
		\tfrac{2-\lambda}{2\lambda\gamma}
		{}+{}
		\tfrac{\sigma_{\sDRS}}{\lambda}
		(\tfrac12-\tfrac{\gamma L_{\sDRS}}{\lambda}).
	\end{equation}

\begin{proof}
		\newcommand\x\xi%
		Let \((u^+,v^+)\) be generated by one \ref{DRS} iteration starting at \(s^+\).
		Then,
		\begin{align*}
			\DRE(s^+)
		{}={} &
			\min_{w\in\R^n}\set{
				\sDRS(u^+)
				{}+{}
				\nsDRS(w)
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{w-u^+}
				{}+{}
				\tfrac{1}{2\gamma}
				\|w-u^+\|^2
			}
		\end{align*}
		and the minimum is attained at \(w=v^+\).
		Therefore, letting \(\rho\) be as in \cref{thm:rho},
		{\mathtight[0.9]%
			\begin{align*}
				\DRE(s^+)
			{}\leq{} &
				\sDRS(u^+)
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u^+}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			{}={} &
				\smashunderbracket[0.5pt]{
					\sDRS(u^+)
					{}+{}
					\innprod{\nabla\sDRS(u^+)}{u-u^+}
				}{}
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			% 			\dueto{\cref{thm:rho}}
			{}\overrel[\leq]{\llap{\cref{thm:rho}}}{} &
				\smashoverbracket[0.5pt]{
					\sDRS(u)
					{}-{}
					\rho(u,u^+)
				}{}
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			{}={} &
				\sDRS(u)
				{}-{}
				\rho(u,u^+)
				{}+{}
				\innprod{\nabla\sDRS(u)}{v-u}
% 				\innprod{\nabla\sDRS(\fillwidthof[c]{u^+}{u})}{v-u}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			&
				{+{}}
				\innprod{\nabla\sDRS(u^+)-\nabla\sDRS(u)}{v-u}
			\\
			{}={} &
				\DRE(s)
				{}-{}
				\rho(u,u^+)
				{}+{}
				\innprod{\nabla\sDRS(u^+)-\nabla\sDRS(u)}{v-u}
				{}+{}
				\tfrac{1}{2\gamma}
				\|u-u^+\|^2
				{}+{}
				\tfrac1\gamma
				\innprod{u^+-u}{u-v}.
			\end{align*}%
		}%
		Since
		\(
			u-v
		{}={}
			\tfrac1\lambda(s-s^+)
		{}={}
			\tfrac1\lambda(u-u^+)
			{}+{}
			\tfrac\gamma\lambda(\nabla\sDRS(u)-\nabla\sDRS(u^+))
		\),
		as it follows from \cref{thm:proxfEquiv}, it all simplifies to
		\begin{equation}\label{eq:DRE:SD0}
			\DRE(s)
			{}-{}
			\DRE(s^+)
		{}\geq{}
			\tfrac{2-\lambda}{2\gamma\lambda}
			\|u-u^+\|^2
			{}-{}
			\tfrac\gamma\lambda
			\|\nabla\sDRS(u^+)-\nabla\sDRS(u)\|^2
			{}+{}
			\rho(u,u^+).
		\end{equation}
		It will suffice to show that
		\[
			\DRE(s)-\DRE(s^+)
		{}\geq{}
			c
			\|u-u^+\|^2;
		\]
		inequality \eqref{eq:DRE:SD} will then follow from the \(\tfrac{1}{1+\gamma L_{\sDRS}}\)-strong monotonicity of \(\prox_{\gamma\sDRS}\), see \cref{thm:proxfLip}.
% 		\[
% 			\|u-u^+\|^2
% 		{}\geq{}
% 			\tfrac{1}{(1+\gamma L_{\sDRS})^2}
% 			\|s-s^+\|^2
% 		\]
		We now proceed by cases.
		\begin{proofitemize}
		\item\textbf{Case 1: \(\lambda\in(0,2)\).}

			\noindent
			Let \(\sigma\coloneqq-[\sigma_{\sDRS}]_-=\min\set{\sigma_{\sDRS},0}\) and \(L\geq L_{\sDRS}\) be such that \(L+\sigma>0\); the value of such an \(L\) will be fixed later.
			Then, \(\sigma\leq0\) and \(\sDRS\) is \(L\)-smooth and \(\sigma\)-hypoconvex.
			We may thus choose \(\rho(u,u^+)\) as in \cref{thm:hypo:rho1} with these values of \(L\) and \(\sigma\).
			Inequality \eqref{eq:DRE:SD0} then becomes
			\[
				\tfrac{\DRE(s)-\DRE(s^+)}{L}
			{}\geq{}
				\left(
					\tfrac{2-\lambda}{2\lambda\x}
					{}+{}
					\tfrac{p}{2(1+p)}
				\right)
				\|u^+-u\|^2
				{}+{}
				\tfrac{1}{L^2}
				\left(
					\tfrac{1}{2(1+p)}
					{}-{}
					\tfrac{\x}{\lambda}
				\right)
				\|\nabla\sDRS(u^+)-\nabla\sDRS(u)\|^2,
			\]
			where \(\x\coloneqq\gamma L\) and \(p\coloneqq\nicefrac\sigma L\in(-1,0]\).
			Since \(\nabla\sDRS\) is \(L_{\sDRS}\)-Lipschitz continuous, the claim holds provided that the constant
			\begin{equation}\label{eq:c}
				\frac cL
			{}={}
				\begin{ifcases}
					\tfrac{2-\lambda}{2\lambda\x}
					{}+{}
					\tfrac{p}{2(1+p)}
				&
					0
					{}<{}
					\tfrac{1}{2(1+p)}
					{}-{}
					\tfrac{\x}{\lambda}
				\\[3pt]
					\tfrac{2-\lambda}{2\lambda\x}
					{}+{}
					\tfrac{p}{2(1+p)}
					{}+{}
					\tfrac{L_{\sDRS}^2}{L^2}
					\left(
						\tfrac{1}{2(1+p)}
						{}-{}
						\tfrac{\x}{\lambda}
					\right)
				\otherwise[otherwise,]
				\end{ifcases}
			\end{equation}
			is strictly positive.
% 			
			Now, let us consider two subcases:
			\begin{itemize}
			\item\textbf{Case 1a:} \(0<\lambda\leq 2(1+\nicefrac{\sigma}{L_{\sDRS}})\).

				Then,
				\(
					\sigma\geq -\frac{2-\lambda}{2}L_{\sDRS}>-L_{\sDRS}
				\)
				and we can take \(L=L_{\sDRS}\).
				Consequently, \(p=\nicefrac{\sigma}{L_{\sDRS}}\), \(\x=\gamma L_{\sDRS}\), and \eqref{eq:c} becomes
				\begin{equation}\label{eq:cbar}
					\frac{c}{L_{\sDRS}}
				{}={}
					\frac{2-\lambda}{2\lambda\gamma L_{\sDRS}}
					{}+{}
					\begin{ifcases}
						\tfrac{p}{2(1+p)}
					&
						\gamma
						{}<{}
						\tfrac{\lambda}{2(1+p)}
					\\[3pt]
						\tfrac{1}{2}
						{}-{}
						\tfrac{\gamma L_{\sDRS}}{\lambda}
					\otherwise.
					\end{ifcases}
				\end{equation}
				Let us verify that in this case any \(\gamma\) such that \(\gamma<\nicefrac{1}{L_{\sDRS}}\) yields a strictly positive coefficient \(c\).
				If \(0<\gamma L_{\sDRS}<\frac{\lambda}{2(1+p)}\leq 1\), then
				\[
					\tfrac{c}{L_{\sDRS}}
				{}={}
					\tfrac{2-\lambda}{2\lambda\gamma L_{\sDRS}}
					{}+{}
					\tfrac{p}{2(1+p)}
				{}>{}
					\tfrac{2-\lambda}{2\lambda}
					{}+{}
					\tfrac{p}{\lambda}
				{}={}
					\tfrac{1+p}{\lambda}
					{}-{}
					\tfrac{1}{2}
				{}\geq{}
					0,
				\]
				where in the inequality we used the fact that \(\lambda<2\) and \(p\leq0\).
				If instead \(\frac{\lambda}{2(1+p)}<\gamma L_{\sDRS}<1\), then
				\[
					\tfrac{c}{L_{\sDRS}}
				{}={}
					\tfrac{2-\lambda}{2\lambda\gamma L_{\sDRS}}
					{}+{}
					\tfrac{1}{2}
					{}-{}
					\tfrac{\gamma L_{\sDRS}}{\lambda}
				{}>{}
					\tfrac{2-\lambda}{2\lambda}
					{}+{}
					\tfrac{1}{2}
					{}-{}
					\tfrac{1}{\lambda}
				{}={}
					0.
				\]
				Either way, the sufficient decrease constant \(c\) is strictly positive.
