		\item\textbf{Case 2: \(\lambda\geq2\).}

			\noindent
			In this case we need to assume that \(\sDRS\) is strongly convex, that is, that \(\sigma_{\sDRS}>0\).
			Instead of considering a single expression of \(\rho\), we will rather take a convex combination of those in \cref{thm:hypo:rho0,thm:hypo:rho1}, namely
			\[
				\rho(u,u^+)
			{}={}
				(1-\alpha)\tfrac{\sigma_{\sDRS}}{2}\|u-u^+\|^2
				{}+{}
				\alpha\tfrac{1}{2L_{\sDRS}}\|\nabla\sDRS(u)-\nabla\sDRS(u^+)\|^2
			\]
			for some \(\alpha\in[0,1]\) to be determined.
			\eqref{eq:DRE:SD0} then becomes
			\[
				\tfrac{
					\DRE(s)-\DRE(s^+)
				}{
					L_{\sDRS}
				}
			{}\geq{}
				\left(
					\tfrac{2-\lambda}{2\lambda\xi}
					{}+{}
					\tfrac{(1-\alpha)p}{2}
				\right)
				\|u-u^+\|^2
				{}+{}
				\tfrac{1}{L_{\sDRS}^2}
				\left(
					\tfrac{\alpha}{2}
					{}-{}
					\tfrac{\xi}{\lambda}
				\right)
				\|\nabla\sDRS(u)-\nabla\sDRS(u^+)\|^2,
			\]
			where \(\x\coloneqq\gamma L_{\sDRS}\) and \(p\coloneqq\nicefrac{\sigma_{\sDRS}}{L_{\sDRS}}\in(0,1]\).
			By restricting \(\xi\in(0,1)\), since \(\lambda\geq2\) one can take
			\(
				\alpha
			{}\coloneqq{}
				\nicefrac{2\xi}{\lambda}
			{}\in{}
				(0,1)
			\)
			to make the coefficient multiplying the gradient norm vanish.
			We then obtain
			\begin{equation}\label{eq:clambda2}
				\tfrac{c}{L_{\sDRS}}
			{}={}
				\tfrac{2-\lambda}{2\lambda\xi}
				{}+{}
				\tfrac{(\lambda-2\xi)p}{2\lambda}.
			\end{equation}
			Imposing \(c>0\) results in the following second-order equation in variable \(\xi\),
			\begin{equation}\label{eq:xi}
				2p\xi^2-p\lambda\xi+(\lambda-2)
			{}<{}
				0.
			\end{equation}
			The discriminant is
			\(
				\Delta
			{}\coloneqq{}
				(p\lambda)^2
				{}-{}
				8p(\lambda-2)
			\),
			which, for \(\lambda\geq2\), is strictly positive iff
			\[
				2
			{}\leq{}
				\lambda
			{}<{}
				\tfrac{4}{1+\sqrt{1-p}}
			~~\vee~~
				\lambda
			{}>{}
				\tfrac{4}{1-\sqrt{1-p}}.
			\]
			Denoting
			\(
				\delta
			{}\coloneqq{}
				\sqrt\Delta
			{}={}
				\sqrt{
					(p\lambda)^2
					{}-{}
					8p(\lambda-2)
				}
			\),
			the solution to \eqref{eq:xi} is
			\(
				\tfrac{
					p\lambda
					{}-{}
					\delta
				}{
					4p
				}
			{}<{}
				\x
			{}<{}
				\tfrac{
					p\lambda
					{}+{}
					\delta
				}{
					4p
				}
			\).
			However, the case \(\lambda\geq 4\) has to be discarded, as
			\(
				\tfrac{p\lambda-\delta}{4p}
			{}>{}
				1
			\)
			in this case, contradicting the fact that \(p\leq1\).
			To see this, suppose \(\lambda\geq4\).
			Then,
			\begin{align*}
				\tfrac{
					p\lambda
					{}-{}
					\delta
				}{
					4p
				}
			{}<{}
				1
			~~\Leftrightarrow~~ &
				p(\lambda-4)
			{}<{}
				\delta
			\\
			~~\Leftrightarrow~~ &
				p^2(\lambda-4)^2
			{}<{}
				\Delta
			{}={}
				(p\lambda)^2
				{}-{}
				8p(\lambda-2)
			\\
			~~\Leftrightarrow~~ &
				p(2-\lambda)
			{}<{}
				2-\lambda,
			\end{align*}
			hence \(p>1\), which contradicts the fact that \(\sigma_{\sDRS}\leq L_{\sDRS}\).
% 			Here and in the second implication we used the assumption \(\lambda\geq4\).
			Thus, the only feasible ranges are the ones given in \eqref{eq:lambda>=2}, hence the claimed sufficient decrease constant \(c\), cf. \eqref{eq:clambda2}.
			\qedhere
		\end{proofitemize}
% 		Also in this case, the claimed range of \(\gamma\) and value of \(c\) have been found.
	\end{proof}

\begin{proof}
