		{}={} &
			\min_{w\in\R^n}\set{
				\sDRS(u^+)
				{}+{}
				\nsDRS(w)
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{w-u^+}
				{}+{}
				\tfrac{1}{2\gamma}
				\|w-u^+\|^2
			}
		\end{align*}
		and the minimum is attained at \(w=v^+\).

		Therefore, letting \(\rho\) be as in \cref{thm:rho},
		{\mathtight[0.9]%
			\begin{align*}
				\DRE(s^+)
			{}\leq{} &
				\sDRS(u^+)
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u^+}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			{}={} &
				\smashunderbracket[0.5pt]{
					\sDRS(u^+)
					{}+{}
					\innprod{\nabla\sDRS(u^+)}{u-u^+}
