				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			% 			\dueto{\cref{thm:rho}}
			{}\overrel[\leq]{\llap{\cref{thm:rho}}}{} &
				\smashoverbracket[0.5pt]{
					\sDRS(u)
					{}-{}
					\rho(u,u^+)
				}{}
				{}+{}
				\innprod{\nabla\sDRS(u^+)}{v-u}
				{}+{}
				\nsDRS(v)
				{}+{}
				\tfrac{1}{2\gamma}
				\|u^+-v\|^2
			\\
			{}={} &
